package io.github.phiscript.root;import android.content.Context;import io.github.phiscript.capture.CourseEngineRegression;public class RootWarmup implements AutoCloseable {private final RootClient client=new RootClient();private boolean taken;public RootWarmup(Context c,int w,int h){CourseEngineRegression.warmed++;android.os.SystemClock.now+=1000;}public void check(){}public RootClient take(){taken=true;return client;}public void close(){if(!taken)client.close();}}
